function typeformAirtableFields({ response }) {
  if (!response || typeof response !== 'object') throw new Error('Expected a complete Typeform response');
  const form = response;
  if (!Array.isArray(form.definition?.fields) || !Array.isArray(form.answers)) throw new Error('Expected the complete form definition and answers');
  const titles = new Map();
  for (const field of form.definition.fields) {
    if (!field || typeof field.id !== 'string' || !field.id || typeof field.title !== 'string' || !field.title.trim() || titles.has(field.id)) throw new Error('Invalid or repeated Typeform field definition');
    titles.set(field.id, field.title.replace(/\{\{/g, '[').replace(/\}\}/g, ']'));
  }
  const entries = [], used = new Set();
  for (const answer of form.answers) {
    const title = titles.get(answer?.field?.id);
    if (title === undefined || used.has(title) || typeof answer.type !== 'string' || !Object.hasOwn(answer, answer.type) || answer[answer.type] == null) throw new Error('Missing, repeated or ambiguous Typeform answer');
    used.add(title);
    let value = answer[answer.type];
    if (value !== null && typeof value === 'object') {
      for (const key of ['label', 'labels']) {
        if (Object.hasOwn(value, key) && value[key] !== undefined) { value = value[key]; break; }
      }
    }
    if (title !== 'id') entries.push([title, value]);
  }
  if (!entries.length) throw new Error('No answer fields remain for Airtable');
  return { records: [{ fields: Object.fromEntries(entries) }] };
}

if($json.event_type!=="form_response")throw new Error("Expected a completed Typeform response");return {json:typeformAirtableFields({response:$json.form_response}).records[0].fields};

function airtableFormRecord({ records }) {
  if (!Array.isArray(records) || records.length !== 1 || typeof records[0]?.id !== 'string' || !records[0].id || !records[0].fields || typeof records[0].fields !== 'object' || Array.isArray(records[0].fields)) throw new Error('Airtable did not confirm one saved record; creation may already have occurred');
  return { record: records[0] };
}

return {json:airtableFormRecord({records:[$json]})};
